pub fn find_route(route_id: u16) -> Option<&'static RouteProfile> {
    ROUTE_PROFILES
        .iter()
        .find(|profile| profile.route_id == route_id)
}

pub fn corridor_bias(corridor: u16) -> u32 {
    let mut value = corridor as u32;
    for profile in ROUTE_PROFILES.iter().filter(|p| p.corridor == corridor) {
        value = value.rotate_left((profile.release_class & 15) as u32) ^ profile.risk_seed;
    }
    value
}
